const PRECACHE_SET = new Set(PRECACHE);

// Same-origin path prefixes that are cache-first even when not precached
// (runtime fill into the shell cache).
const SHELL_PREFIXES = ['/_expo/', '/assets/', '/coin/', '/replays/', '/icons/', '/fonts/'];

// --- install: precache the shell -------------------------------------------

self.addEventListener('install', function (event) {
  // Deliberately NOT calling skipWaiting() here (MASTER-EXECUTION 1.6a).
  // Skipping unconditionally meant a new worker installed, activated, and
  // claimed clients in one breath -- reg.waiting was always null, so a
  // returning visitor was silently upgraded mid-session with no chance to
  // show a "fresh edition" chip. Now: first-ever visit has no active worker,
  // so install -> activate still runs immediately (unchanged first-load
  // behavior); a REPEAT visit with an already-active worker parks the new
  // one in the 'waiting' slot until the page explicitly posts SKIP_WAITING
  // (see the message listener below), which the update-chip UI triggers on tap.
  event.waitUntil(precacheShell());
});

// --- message: page asks the waiting worker to take over ---------------

self.addEventListener('message', function (event) {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

async function precacheShell() {
  const cache = await caches.open(SHELL_CACHE);
  // Chunks of 20, each entry individually failure-tolerant: a single 404
  // must not brick install.
  for (let i = 0; i < PRECACHE.length; i += 20) {
    const chunk = PRECACHE.slice(i, i + 20);
    await Promise.all(chunk.map(async function (url) {
      try {
        await cache.add(url);
      } catch (err) {
        // Tolerated: the file will be runtime-filled on first use instead.
      }
    }));
  }
  // '/' is an alias for index.html (navigations fall back to it too).
  try {
    const index = await cache.match('/index.html');
    if (index) await cache.put('/', index.clone());
  } catch (err) { /* non-fatal */ }
}

// --- activate: drop old shells, claim, warm media in background ------------

self.addEventListener('activate', function (event) {
  event.waitUntil((async function () {
    const names = await caches.keys();
    await Promise.all(names.map(function (name) {
      if (name.indexOf('gr-shell-') === 0 && name !== SHELL_CACHE) {
        return caches.delete(name);
      }
      return Promise.resolve();
    }));
    await self.clients.claim();
    // Background warm-up: intentionally NOT awaited inside waitUntil, so it
    // is abandonable — the browser may terminate the worker mid-warm and
    // nothing breaks; already-cached entries are skipped on the next pass.
    warmMedia().catch(function () { /* fully failure-tolerant */ });
  })());
});

async function warmMedia() {
  if (WARM_URLS.length === 0) return;
  const cache = await caches.open(MEDIA_CACHE);
  for (let i = 0; i < WARM_URLS.length; i += WARM_CONCURRENCY) {
    const chunk = WARM_URLS.slice(i, i + WARM_CONCURRENCY);
    await Promise.all(chunk.map(async function (url) {
      try {
        const hit = await cache.match(url);
        if (hit) return;
        const res = await fetch(url, { mode: 'cors' });
        if (isCacheable(res)) await cache.put(url, res);
      } catch (err) {
        // Network error just stops that entry; never throws unhandled.
      }
    }));
  }
}

// Only cache ok (but not partial 206) or opaque responses.
function isCacheable(res) {
  if (!res) return false;
  if (res.type === 'opaque') return true;
  return res.ok && res.status !== 206;
}

// --- fetch ------------------------------------------------------------------

self.addEventListener('fetch', function (event) {
  const req = event.request;
  if (req.method !== 'GET') return; // only ever handle GET

  let url;
  try {
    url = new URL(req.url);
  } catch (err) {
    return;
  }

  // Phone-truth guard (owner iPhone bug, 2026-08): WebKit's media loader
  // fetches .mp4 with Range headers and requires true 206 semantics
  // end-to-end. Answering those from cacheFirst — a cached full 200, or an
  // opaque no-cors partial from fetch(req) — kills every jumbotron/replay
  // clip on iOS with MEDIA_ERR_SRC_NOT_SUPPORTED. Never intercept ranged
  // video: the native loader + the CDN's Accept-Ranges handle it correctly,
  // and the HTTP cache (immutable, max-age=1y) already covers repeats.
  // Non-ranged .mp4 requests still flow through the video cache below.
  if (req.headers.has('range') && url.pathname.toLowerCase().endsWith('.mp4')) {
    return;
  }

  // (a) navigations: network-first, fall back to the cached shell.
  if (req.mode === 'navigate') {
    event.respondWith((async function () {
      try {
        return await fetch(req);
      } catch (err) {
        const cached = await caches.match('/index.html');
        if (cached) return cached;
        throw err;
      }
    })());
    return;
  }

  // (b) assets host: cache-first media; .mp4 goes to the LRU'd video cache.
  if (url.origin === ASSETS_ORIGIN) {
    const isVideo = url.pathname.toLowerCase().endsWith('.mp4');
    event.respondWith(cacheFirst(req, isVideo ? VIDEO_CACHE : MEDIA_CACHE, isVideo));
    return;
  }

  // (c) same-origin shell paths: cache-first with runtime fill.
  if (url.origin === self.location.origin) {
    const p = url.pathname;
    const isShellPath = SHELL_PREFIXES.some(function (pre) { return p.indexOf(pre) === 0; });
    if (isShellPath || PRECACHE_SET.has(p)) {
      event.respondWith(cacheFirst(req, SHELL_CACHE, false));
      return;
    }
  }

  // (d) everything else (supabase, netlify functions, other origins):
  // pass through untouched — no respondWith.
});

async function cacheFirst(req, cacheName, lru) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(req);
  if (hit) return hit;
  const res = await fetch(req);
  if (isCacheable(res)) {
    try {
      await cache.put(req, res.clone());
      if (lru) await enforceLru(cache, VIDEO_CACHE_MAX);
    } catch (err) {
      // Quota or clone failures never break the response path.
    }
  }
  return res;
}

// Simple LRU by insertion order (the Cache API preserves it well enough):
// on insert, if over cap, delete the oldest entries.
async function enforceLru(cache, max) {
  const keys = await cache.keys();
  if (keys.length <= max) return;
  const excess = keys.length - max;
  for (let i = 0; i < excess; i += 1) {
    try {
      await cache.delete(keys[i]);
    } catch (err) { /* non-fatal */ }
  }
}
